inline fun <reified Main : ScreenModel> Navigation(modifier: Modifier = Modifier, deeplink: DeepLink<ScreenManager> = DeepLink.default(), noinline transitionSpecProvider: AnimatedContentTransitionScope<*>.() -> ContentTransform = {
                slideIntoContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.Start,
                    animationSpec = tween(durationMillis = 400)
                ) togetherWith slideOutOfContainer(
                    towards = AnimatedContentTransitionScope.SlideDirection.End,
                    animationSpec = tween(durationMillis = 400)
                )
            }, noinline builder: ScreenRegistry.Builder.() -> Unit)

